async function analyzeCode(){const code=$('barcodeInput').value.trim();if(!/^\d{8,14}$/.test(code)){toast('Introduce un código de barras válido.');return}stopScanner();toast('Buscando el producto…');try{const d=await fetchJSON('https://world.openbeautyfacts.org/api/v3/product/'+encodeURIComponent(code)+'?product_type=beauty&lc=es');if(d.status!=='success'||!d.product){showUnverified('Código '+code,'No hemos encontrado una ficha de producto verificable en la base consultada.');return}setProductFromAPI(d.product,code)}catch(e){showUnverified('Código '+code,'No se ha podido consultar la base de productos. Comprueba tu conexión o usa la foto de la etiqueta.')}}
