async function localOCRAssetsAvailable(){try{const paths=['assets/vendor/tesseract/tesseract.min.js','assets/vendor/tesseract/worker.min.js','assets/vendor/tesseract/tesseract-core.wasm.js','assets/vendor/tesseract/lang/spa.traineddata.gz','assets/vendor/tesseract/lang/eng.traineddata.gz'];const results=await Promise.all(paths.map(p=>fetch(p,{method:'HEAD',cache:'no-store'}).then(r=>r.ok).catch(()=>false)));return results.every(Boolean)}catch(e){return false}}
function loadTesseract(){return new Promise((res,rej)=>{const existing=document.querySelector('script[data-desinzi-tesseract]');if(existing){if(window.Tesseract){res();return}existing.addEventListener('load',res,{once:true});existing.addEventListener('error',rej,{once:true});return}const sc=document.createElement('script');sc.dataset.desinziTesseract='1';sc.src=OCR_LOCAL_SCRIPT;sc.onload=res;sc.onerror=()=>{const fallback=document.createElement('script');fallback.dataset.desinziTesseract='1';fallback.src=OCR_CDN_SCRIPT;fallback.onload=res;fallback.onerror=()=>rej(new Error('No se pudo cargar Tesseract.js'));document.head.appendChild(fallback)};document.head.appendChild(sc)})}
