function startCompareSearch(){show('compareSearch');setTimeout(()=>$('compareSearchInput')?.focus(),150)}
function searchCompareProduct(){const q=$('compareSearchInput').value.trim();if(!q){toast('Escribe una marca o producto.');return}const box=$('compareSearchResults');box.innerHTML='<div class="card"><b>Buscando producto B…</b><p class="sub">La base consultada aporta datos de producto; no es una certificación de seguridad.</p></div>';fetchJSON('https://world.openbeautyfacts.org/cgi/search.pl?search_terms='+encodeURIComponent(q)+'&search_simple=1&action=process&json=1&page_size=8').then(d=>{const ps=(d.products||[]).filter(p=>p.product_name||p.product_name_es);if(!ps.length){box.innerHTML='<div class="notice">No se ha encontrado una coincidencia suficiente.</div>';return}window.__compareProducts=ps;box.innerHTML=ps.map((p,i)=>'<button class="choice" data-action="select-compare-product" data-index="'+i+'"><span class="ico">🧴</span><span><b>'+escapeHtml(p.product_name||p.product_name_es)+'</b><small>'+escapeHtml(p.brands||'Marca no indicada')+(p.code?' · '+escapeHtml(p.code):'')+'</small></span><span class="arrow">›</span></button>').join('')}).catch(()=>box.innerHTML='<div class="notice">No se ha podido consultar la base. Comprueba la conexión.</div>')}
function selectCompareProduct(i){const p=window.__compareProducts?.[i];if(!p)return;compareProductB={source:'Open Beauty Facts',code:p.code||'',product:p};renderCompare();show('compare')}
function canonicalForCrosscheck(raw){
  const m=ingredientMatch(raw);
  if(m&&m.match!=='possible')return {key:m.key,match:m.match,entry:m.entry};
  return {key:null,match:m?.match||'unknown',entry:m?.entry||null};
}
function crosscheckINCI(photoText,dbText){
  const photo=splitINCI(photoText), db=splitINCI(dbText);
  const toRecords=(items,side)=>items.map((raw,index)=>({raw,index,side,...canonicalForCrosscheck(raw)}));
  const P=toRecords(photo,'photo'), D=toRecords(db,'database');
  const pBy=new Map(), dBy=new Map();
  for(const r of P)if(r.key){const a=pBy.get(r.key)||[];a.push(r);pBy.set(r.key,a)}
  for(const r of D)if(r.key){const a=dBy.get(r.key)||[];a.push(r);dBy.set(r.key,a)}
  const keys=[...new Set([...pBy.keys(),...dBy.keys()])];
  const common=[],photoOnly=[],dbOnly=[];
  for(const key of keys){const p=pBy.get(key)||[],d=dBy.get(key)||[];const n=Math.max(p.length,d.length);for(let i=0;i<n;i++){if(p[i]&&d[i])common.push({key,photo:p[i],db:d[i],relation:p[i].raw===d[i].raw?'exact-text':'verified-same-ingredient'});else if(p[i])photoOnly.push(p[i]);else if(d[i])dbOnly.push(d[i])}}
  const unresolvedPhoto=P.filter(r=>!r.key),unresolvedDb=D.filter(r=>!r.key);
  const orderPhoto=P.filter(r=>r.key).map(r=>r.key),orderDb=D.filter(r=>r.key).map(r=>r.key);
  const sameOrder=orderPhoto.length===orderDb.length&&orderPhoto.every((k,i)=>k===orderDb[i]);
  return {photo,db,common,photoOnly,dbOnly,unresolvedPhoto,unresolvedDb,sameOrder};
}
function renderCrosscheckRow(item,label){const rel=item.relation==='exact-text'?'Coincidencia textual':'Mismo ingrediente identificado mediante la base verificada';return '<div class="row"><span class="dot green">✓</span><span><b>'+escapeHtml(item.photo.raw)+'</b> ↔ <b>'+escapeHtml(item.db.raw)+'</b><br><span class="small">'+rel+'</span></span></div>'}
function interpretCrosscheck(r){const unresolved=r.unresolvedPhoto.length+r.unresolvedDb.length;const exclusive=r.photoOnly.length+r.dbOnly.length;if(r.sameOrder&&exclusive===0&&unresolved===0&&r.photo.length===r.db.length)return {tone:'green',level:'coherente',title:'Los dos textos son coherentes con los datos comparados.',body:'No se han detectado diferencias identificables entre la etiqueta fotografiada y la ficha consultada. Esto no certifica la fórmula ni la seguridad del producto.'};if(unresolved>0)return {tone:'blue',level:'limitada',title:'La comparación está limitada por texto no identificable.',body:'Hay elementos que no se han podido identificar con suficiente confianza. Una diferencia aparente puede proceder del OCR o de una ficha incompleta; no se fuerza una conclusión.'};if(exclusive>0)return {tone:'amber',level:'requiere revisión',title:'Hay diferencias entre los textos disponibles.',body:'Puede haber varias explicaciones: ficha desactualizada, diferencia de presentación o mercado, reformulación o lectura incompleta. Con estos datos no se puede determinar cuál es la causa.'};return {tone:'blue',level:'revisión de orden',title:'El contenido parece coincidir, pero el orden difiere.',body:'El orden del INCI puede variar en los datos recuperados o por la forma en que se ha transcrito. Por sí solo no demuestra una reformulación ni un incumplimiento.'};}
function renderCrosscheckInterpretation(r){const i=interpretCrosscheck(r);return '<div class="notice"><span class="tag '+i.tone+'">'+i.title+'</span><p class="small u-mt-8"><b>Nivel de interpretación: '+i.level+'.</b> '+i.body+'</p><p class="small"><b>Qué hacer:</b> si la diferencia es relevante, revisar la fotografía original, la lista INCI completa del envase y la fecha/fuente de la ficha antes de extraer conclusiones.</p></div>';}
function renderLabelCrosscheckVisibility(){const box=$('labelCrosscheckCard');if(!box)return;const hasPhoto=!!window.__dzLastOCRText;const hasDb=!!productINCI(currentProduct);box.classList.toggle('hidden',!(hasPhoto&&hasDb));if(hasPhoto&&hasDb)renderLabelCrosscheck()}
function renderLabelCrosscheck(){const box=$('labelCrosscheckResult');if(!box||!currentProduct||!window.__dzLastOCRText)return;const db=productINCI(currentProduct),photo=window.__dzLastOCRText,r=crosscheckINCI(photo,db);let html='<div class="card"><span class="badge">COMPROBACIÓN CRUZADA</span><h3>Etiqueta fotografiada ↔ ficha consultada</h3><p class="small">La comparación detecta diferencias entre los textos disponibles. No demuestra por sí sola que exista un cambio de fórmula, un error de la marca o un incumplimiento.</p>';
html+='<div class="two-col"><div><span class="badge">ETIQUETA / OCR</span><h3>'+r.photo.length+'</h3><p class="small">elementos leídos</p></div><div><span class="badge">OPEN BEAUTY FACTS</span><h3>'+r.db.length+'</h3><p class="small">elementos declarados en la ficha</p></div></div>';
if(r.common.length)html+='<h4>Coincidencias identificadas ('+r.common.length+')</h4>'+r.common.slice(0,80).map(x=>renderCrosscheckRow(x)).join('');
if(r.photoOnly.length)html+='<h4>Solo aparecen en la etiqueta fotografiada ('+r.photoOnly.length+')</h4>'+r.photoOnly.map(x=>'<div class="row"><span class="dot amber">!</span><span><b>'+escapeHtml(x.raw)+'</b><br><span class="small">No aparece una coincidencia identificable en la ficha consultada.</span></span></div>').join('');
if(r.dbOnly.length)html+='<h4>Solo aparecen en la ficha consultada ('+r.dbOnly.length+')</h4>'+r.dbOnly.map(x=>'<div class="row"><span class="dot amber">!</span><span><b>'+escapeHtml(x.raw)+'</b><br><span class="small">No aparece una coincidencia identificable en el texto fotografiado.</span></span></div>').join('');
if(r.unresolvedPhoto.length)html+='<h4>Texto de la foto no identificable ('+r.unresolvedPhoto.length+')</h4>'+r.unresolvedPhoto.map(x=>'<div class="row"><span class="dot blue">?</span><span><b>'+escapeHtml(x.raw)+'</b><br><span class="small">No se fuerza una equivalencia.</span></span></div>').join('');
if(r.unresolvedDb.length)html+='<h4>Texto de la ficha no identificable ('+r.unresolvedDb.length+')</h4>'+r.unresolvedDb.map(x=>'<div class="row"><span class="dot blue">?</span><span><b>'+escapeHtml(x.raw)+'</b><br><span class="small">No se fuerza una equivalencia.</span></span></div>').join('');
html+=renderCrosscheckInterpretation(r);html+='<div class="notice"><b>Orden:</b> '+(r.sameOrder?'los ingredientes identificables aparecen en el mismo orden.':'hay diferencias de orden o de contenido; el orden por sí solo no demuestra un cambio de fórmula.')+'</div>';
html+='<div class="small">La ficha externa se trata como dato de referencia, no como certificación. Open Beauty Facts advierte que sus datos son aportados voluntariamente y pueden no ser completos o exactos.</div></div>';
box.innerHTML=html;}
function runLabelCrosscheck(){if(!window.__dzLastOCRText){toast('Primero realiza una lectura OCR de la etiqueta.');return}if(!productINCI(currentProduct)){toast('El producto consultado no tiene un INCI disponible para comparar.');return}renderLabelCrosscheck();const target=$('labelCrosscheckResult');if(target)target.scrollIntoView({behavior:'smooth',block:'start'})}
function productINCI(obj){return normalizeINCI(obj?.product?.ingredients_text_es||obj?.product?.ingredients_text||'')}
function productTitle(obj){return obj?.product?.product_name||obj?.product?.product_name_es||'Producto sin nombre declarado'}
function compareIngredientProfile(rawItems){
 const rows=rawItems.map(raw=>{const k=getKnowledge(raw);return {raw,k,known:!!k,rule:!!k?.regulatoryRule,evidence:k?.evidence||'unknown',criterion:criterionMatches(k)}});
 return {rows,known:rows.filter(x=>x.known).length,unknown:rows.filter(x=>!x.known).length,regulated:rows.filter(x=>x.rule).length,nonStrong:rows.filter(x=>x.evidence!=='strong').length,focus:rows.filter(x=>x.criterion).length};
}
function comparisonInterpretation(pa,pb,common,onlyA,onlyB){
 const facts=[];
 if(pa.unknown||pb.unknown)facts.push('Hi ha ingredients sense una ficha de coneixement suficient; no es pot completar la comparació només amb la base local.');
 if(pa.regulated!==pb.regulated)facts.push('El recompte de substàncies amb regla regulatoria identificada és diferent, però això no indica quin producte compleix millor: cal context i concentració.');
 if(pa.nonStrong!==pb.nonStrong)facts.push('El nivell d’evidència disponible és diferent en alguns ingredients; això mesura la informació disponible, no una puntuació de seguretat del producte.');
 if(common.length===0&&onlyA.length&&onlyB.length)facts.push('No hi ha coincidències exactes entre els textos disponibles; això no permet concloure que les fórmules siguin incompatibles ni que una sigui millor.');
 return facts.length?facts:['Amb els textos disponibles, la comparació és descriptiva. No s’assigna un guanyador ni una puntuació de seguretat.'];
}
function renderCompare(){
 const a=currentProduct,b=compareProductB;
 $('compareAName').textContent=a?productTitle(a):'Sin producto';$('compareAMeta').textContent=a?((a.product.brands||'Marca no indicada')+' · '+(productINCI(a)?'INCI disponible':'INCI no disponible')):'Analiza primero un producto.';
 $('compareBName').textContent=b?productTitle(b):'Sin producto';$('compareBMeta').textContent=b?((b.product.brands||'Marca no indicada')+' · '+(productINCI(b)?'INCI disponible':'INCI no disponible')):'Añade un segundo producto.';
 if(!a||!b){$('compareEmpty').classList.remove('hidden');$('compareResult').classList.add('hidden');return}
 const A=splitINCI(productINCI(a)),B=splitINCI(productINCI(b));
 const norm=x=>normalizeIngredientKey(x).replace(/\s*\([^)]*\)/g,'').trim();
 const mapA=new Map(A.map(x=>[norm(x),x])),mapB=new Map(B.map(x=>[norm(x),x]));
 const common=[...mapA.keys()].filter(k=>mapB.has(k)),onlyA=[...mapA.keys()].filter(k=>!mapB.has(k)),onlyB=[...mapB.keys()].filter(k=>!mapA.has(k));
 const pa=compareIngredientProfile(A),pb=compareIngredientProfile(B);
 const rows=(keys,map)=>keys.map(k=>{const raw=map.get(k),info=getKnowledge(raw);return '<div class="row"><span class="dot '+(info?.tone||'blue')+'">•</span><span><b>'+escapeHtml(raw)+'</b><br><span class="small">'+escapeHtml(info?.status||'Sin conclusión automática')+'</span>'+(info?.evidence?'<br>'+evidenceBadge(info):'')+'</span></div>'}).join('');
 const metric=(label,value,note)=>'<div class="card"><span class="badge">'+escapeHtml(label)+'</span><h3>'+value+'</h3><p class="small">'+escapeHtml(note)+'</p></div>';
 const notes=comparisonInterpretation(pa,pb,common,onlyA,onlyB).map(x=>'<li>'+escapeHtml(x)+'</li>').join('');
 $('compareEmpty').classList.add('hidden');
 $('compareResult').innerHTML='<div class="two-col">'+metric('A · INCI',A.length,'ingredientes leídos')+metric('B · INCI',B.length,'ingredientes leídos')+'</div><div class="two-col">'+metric('A · conocidos',pa.known,A.length?'entradas identificadas en el motor':'sin INCI')+metric('B · conocidos',pb.known,B.length?'entradas identificadas en el motor':'sin INCI')+'</div><div class="card"><h3>Coinciden ('+common.length+')</h3>'+(common.length?rows(common,mapA):'<p class="sub">No hay coincidencias exactas entre los textos disponibles.</p>')+'</div><div class="card"><h3>Solo en A ('+onlyA.length+')</h3>'+(onlyA.length?rows(onlyA,mapA):'<p class="sub">Ninguno con los datos disponibles.</p>')+'</div><div class="card"><h3>Solo en B ('+onlyB.length+')</h3>'+(onlyB.length?rows(onlyB,mapB):'<p class="sub">Ninguno con los datos disponibles.</p>')+'</div><div class="card"><h3>Lectura responsable</h3><ul class="small">'+notes+'</ul><p class="footer-note">La app no convierte el INCI en una puntuación 0–100 ni declara un “mejor” producto. Concentración, formulación completa, exposición, uso previsto y fecha de mercado pueden cambiar la interpretación.</p></div>';
 $('compareResult').classList.remove('hidden')
}
function searchProduct(){const q=$('searchInput').value.trim();if(!q){toast('Escribe una marca o producto.');return}const box=$('searchResults');box.innerHTML='<div class="card"><b>Buscando en Open Beauty Facts…</b><p class="sub">Los resultados son datos de producto, no una certificación de seguridad.</p></div>';fetchJSON('https://world.openbeautyfacts.org/cgi/search.pl?search_terms='+encodeURIComponent(q)+'&search_simple=1&action=process&json=1&page_size=8').then(d=>{const ps=(d.products||[]).filter(p=>p.product_name||p.product_name_es);if(!ps.length){box.innerHTML='<div class="notice">No se ha encontrado una coincidencia suficiente. Prueba otra búsqueda o usa una foto del INCI.</div>';return}box.innerHTML=ps.map((p,i)=>'<button class="choice" data-action="select-search" data-index="'+i+'"><span class="ico">🧴</span><span><b>'+escapeHtml(p.product_name||p.product_name_es)+'</b><small>'+escapeHtml(p.brands||'Marca no indicada')+'</small></span><span class="arrow">›</span></button>').join('');window.__searchProducts=ps}).catch(()=>box.innerHTML='<div class="notice">No se ha podido consultar la base. Comprueba la conexión.</div>')}
