function readStore(key,fallback=[]){try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback))}catch(e){return fallback}}
function saveHistory(name,detail,extra={}){const h=readStore('desinzero_history');h.unshift({id:extra.id||('h_'+Date.now()),name,detail,date:new Date().toLocaleDateString('es-ES'),code:extra.code||'',inci:extra.inci||'',source:extra.source||'',version:DATA_VERSION});localStorage.setItem('desinzero_history',JSON.stringify(h.slice(0,50)))}
