function getSnapshots(){return readStore('desinzero_snapshots')}
function saveSnapshot(obj){const key=snapshotKey(obj);const snaps=getSnapshots();const old=snaps.find(x=>x.key===key);const snap={key,name:productTitle(obj),code:obj.code||'',inci:productINCI(obj),date:new Date().toISOString(),version:DATA_VERSION};if(old){snap.previousInci=old.inci;snap.inciChanged=old.inci!==snap.inci;snap.previousDate=old.date;snap.previousVersion=old.version}snaps.unshift(snap);const dedup=snaps.filter((x,i,a)=>i===a.findIndex(y=>y.key===x.key));localStorage.setItem('desinzero_snapshots',JSON.stringify(dedup.slice(0,50)));return snap}
function isFavorite(key){return readStore('desinzero_favorites').some(x=>x.key===key)}
function toggleFavoriteCurrent(){if(!currentProduct){toast('Primero analiza un producto.');return}const key=snapshotKey(currentProduct);let f=readStore('desinzero_favorites');if(isFavorite(key)){f=f.filter(x=>x.key!==key);toast('Quitado de favoritos.')}else{f.unshift({key,name:productTitle(currentProduct),code:currentProduct.code||'',date:new Date().toLocaleDateString('es-ES')});toast('Guardado en favoritos.')}localStorage.setItem('desinzero_favorites',JSON.stringify(f.slice(0,50)));updateFavoriteButton();renderHistory()}
function updateFavoriteButton(){const b=$('favoriteBtn');if(b)b.textContent=isFavorite(snapshotKey(currentProduct))?'★ En favoritos':'☆ Guardar en favoritos'}
function openHistoryItem(key){const h=readStore('desinzero_history').find(x=>x.id===key);if(!h){const f=readStore('desinzero_favorites').find(x=>x.key===key);if(f){toast('Los favoritos guardan la referencia; vuelve a buscar el producto para actualizar sus datos.')}return}if(h.inci){$('productName').textContent=h.name;$('productMeta').textContent=h.detail+' · '+h.date;$('confidence').textContent='Registro local consultado';$('sourceDate').textContent=h.version||'Versión anterior';$('ingredientRaw').textContent=h.inci;renderIngredientList(h.inci);show('result')}else toast('Este registro no contiene un INCI recuperable.')}
function historyTab(mode,btn){document.querySelectorAll('#history .tab').forEach(b=>b.classList.remove('active'));btn.classList.add('active');renderHistory(mode)}
