function analyzeClaim(){
 const raw=$('claimInput').value.trim();if(!raw){toast('Escribe primero una promesa.');return}
 const t=raw.toLowerCase();let category='Reivindicación general',tone='blue',title='La frase necesita contexto',body='Una frase comercial no basta para concluir seguridad, eficacia o cumplimiento. DESINZI separará el significado de la promesa, la evidencia necesaria y la información que falta.';
 const checks=[];
 if(/100\s*%|natural|naturale?/.test(t)){category='Origen / “natural”';tone='amber';title='“Natural” no equivale automáticamente a más seguro';body='El origen de un ingrediente o producto no demuestra por sí solo seguridad, eficacia ni ausencia de riesgo.';checks.push('Definir exactamente qué parte se considera natural y con qué criterio.');}
 else if(/sin\s+(tóxic|tox|químic)|libre de tóxic|non.?toxic/.test(t)){category='Seguridad / ausencia';tone='amber';title='“Sin tóxicos” es demasiado ambiguo';body='Hay que identificar qué sustancias, qué peligro, qué concentración y qué exposición se están excluyendo. “Químico” tampoco es una categoría toxicológica.';checks.push('Identificar la lista o criterio concreto detrás de “sin”.');}
 else if(/clínic|clinical|estudio|probado/.test(t)){category='Evidencia / eficacia';tone='amber';title='“Clínicamente probado” necesita evidencia identificable';body='La reivindicación debe poder relacionarse con evidencia adecuada para el beneficio comunicado y con las condiciones en que se realizó.';checks.push('Concretar beneficio, población, diseño del estudio y relación con el producto comunicado.');}
 else if(/limpio|clean|clean beauty/.test(t)){category='Marketing / “clean”';tone='amber';title='“Clean” no es una categoría legal de seguridad';body='Es un concepto comercial que necesita una definición. DESINZI no lo trata como sinónimo de seguro ni su ausencia como sinónimo de peligroso.';checks.push('Definir los criterios concretos que usa la marca.');}
 else if(/no comedog|non.?comedogenic/.test(t)){category='Característica del producto';tone='blue';title='“No comedogénico” requiere una base de prueba';body='Es una afirmación concreta: la etiqueta no permite por sí sola conocer qué método se utilizó ni en qué condiciones se sustenta.';checks.push('Comprobar la evidencia específica que respalda la reivindicación.');}
 else if(/hipoalerg|hypoallergenic/.test(t)){category='Sensibilización / tolerancia';tone='amber';title='“Hipoalergénico” no significa riesgo cero';body='No equivale a que ninguna persona pueda presentar una reacción. Debe interpretarse como una reivindicación que necesita justificación.';checks.push('Comprobar qué criterio y evidencia utiliza la marca para la reivindicación.');}
 else if(/dermatol|dermatologist|dermatológ/.test(t)){category='Respaldo profesional';tone='blue';title='“Dermatológicamente probado” necesita saber qué se probó';body='La expresión por sí sola no explica el protocolo, el beneficio evaluado ni las condiciones del ensayo.';checks.push('Identificar el ensayo y el beneficio concreto comunicado.');}
 else checks.push('Concretar qué resultado promete y qué evidencia permitiría verificarlo.');
 $('claimResult').innerHTML='<div class="card"><span class="tag '+tone+'">'+escapeHtml(category)+'</span><h3 class="u-mt-8">'+escapeHtml(title)+'</h3><p class="sub">'+escapeHtml(body)+'</p><div class="notice"><b>Qué comprobaría DESINZI:</b><ul class="small">'+checks.map(x=>'<li>'+escapeHtml(x)+'</li>').join('')+'<li>Si la comunicación puede inducir a error en su contexto.</li><li>Qué parte es información verificable y qué parte es lenguaje comercial.</li></ul></div><a class="source" href="'+SOURCES.claims+'" target="_blank" rel="noopener noreferrer">Criterios UE para las reivindicaciones cosméticas ↗</a><p class="footer-note">No se emite un veredicto de “verdadero/falso” sin evidencia específica del claim. El motor funciona como orientación informativa.</p></div>'
}
function exportAnalysisReport(){
 if(!currentProduct){toast('Primero analiza un producto.');return}
 const title=productTitle(currentProduct), brand=currentProduct?.product?.brands||'Marca no indicada', inci=productINCI(currentProduct), items=splitINCI(inci);
 const findings=items.map(raw=>{const k=getKnowledge(raw);return {raw,status:k?.status||'No identificado',evidence:k?.evidence||'unknown',note:k?.note||''}});
 const regulated=findings.filter(x=>x.status&&/regul|condic|restric|límite|sujeto/i.test(x.status));
 const unknown=findings.filter(x=>x.status==='No identificado');
 const criteria=getCriteria().filter(x=>x!=='all'); const criteriaText=criteria.length?criteria.join(', '):'Todos'; const lines=['DESINZI · ZERO HUMO — INFORME DE ANÁLISIS','',`Producto: ${title}`,`Marca: ${brand}`,`Fuente: ${currentProduct.source||'No indicada'}`,`Fecha del informe: ${new Date().toLocaleString('es-ES')}`,`Versión de app: ${DATA_VERSION}`,`Base de conocimiento: ${activeKnowledge?.payload?.knowledgeVersion||'No disponible'}`,`Preferencias de presentación activas: ${criteriaText}`,'','CRITERIO','Este informe es informativo. No constituye una evaluación toxicológica, clínica ni jurídica completa. No se inventan datos ausentes.','',`INCI recuperado (${items.length} ingredientes):`,inci||'No disponible','',`Ingredientes identificados por el motor: ${findings.length-unknown.length}/${findings.length}`,`Ingredientes con contexto/regla regulatoria identificada: ${regulated.length}`,`Ingredientes no identificados: ${unknown.length}`,''];
 findings.forEach(x=>{lines.push(`• ${x.raw} — ${x.status} — evidencia: ${x.evidence}${x.note?' — '+x.note:''}`)});
 const ctx=getProductContext();lines.push('',`CONTEXTO REGISTRADO: tipo=${ctx.category||'no indicado'} · edad=${ctx.ageGroup||'no indicada'} · concentración=${ctx.concentration||'no indicada'} · fecha=${ctx.dateChecked||'no indicada'}`,'','LÍMITES','La lista INCI por sí sola no permite conocer necesariamente concentración exacta, exposición, formulación completa, uso previsto o todos los parámetros relevantes.','Fuentes regulatorias y científicas se mantienen en la aplicación y deben verificarse según la fecha aplicable.');
 const blob=new Blob([lines.join('\\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='DESINZI-informe-'+new Date().toISOString().slice(0,10)+'.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Informe guardado en este dispositivo.');
}
