async function sha256Hex(text){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return [...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function checkKnowledgeUpdate(){const out=$('updateStatus');if(!out)return;const base=localStorage.getItem('desinzero_backend')||'';if(!base){out.textContent='Backend de producción: pendiente de desplegar. Se mantiene la base incluida en esta versión.';return}out.textContent='Comprobando versión, esquema, fuentes e integridad…';try{const root=base.replace(/\/$/,'');const m=await fetchJSON(root+'/v1/knowledge/manifest');if(!m.version||!m.payloadUrl||!m.sha256||m.schemaVersion!==KNOWLEDGE_SCHEMA||m.signatureAlgorithm!==UPDATE_SIGNING_ALGORITHM||m.signingKeyId!==UPDATE_SIGNING_KEY_ID||!m.signature)throw new Error('manifest_incompatible');const current=activeKnowledge?.payload?.knowledgeVersion||'';const remote=String(m.version);const cmp=compareDataVersions(remote,current);const payloadUrl=new URL(m.payloadUrl,root).toString();const response=await fetch(payloadUrl,{headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)throw new Error('HTTP '+response.status);const raw=await response.text();const digest=await sha256Hex(raw);if(digest!==String(m.sha256).toLowerCase())throw new Error('integridad_no_verificada');if(!(await verifyKnowledgeSignature(raw,m)))throw new Error('firma_no_verificada');const payload=JSON.parse(raw);if(String(payload.knowledgeVersion)!==remote||payload.schemaVersion!==KNOWLEDGE_SCHEMA)throw new Error('version_o_esquema_no_coincide');const loaded=knowledgeFromPayload(payload);if(!loaded)throw new Error('schema_invalid');const previous=localStorage.getItem('desinzero_verified_knowledge');if(cmp<0){out.textContent='El servidor ofrece una versión anterior; se conserva la base instalada.';return}if(previous) localStorage.setItem('desinzero_verified_knowledge_previous',previous);localStorage.setItem('desinzero_verified_knowledge',JSON.stringify({manifest:m,payload,raw,verifiedAt:new Date().toISOString()}));activeKnowledge=loaded;knowledgeActivationSource='verified-server';const label=$('dataVersionLabel');if(label)label.textContent=remote+' · base verificada';renderKnowledgeAudit();out.textContent=cmp>0?'Nueva base de conocimiento verificada y activada.':'La base instalada coincide con el servidor y su integridad ha sido verificada.'}catch(e){out.textContent='No se ha podido verificar/activar la actualización: '+(e.message==='integridad_no_verificada'?'la integridad no coincide':e.message==='firma_no_verificada'?'la firma criptográfica no es válida':e.message==='version_o_esquema_no_coincide'||e.message==='manifest_incompatible'||e.message==='schema_invalid'?'el contenido no cumple el esquema esperado':e.name==='AbortError'?'tiempo de espera agotado':'conexión no disponible')+'. Se conserva la base anterior.'}}
function renderKnowledgeAudit(){
 const box=$('knowledgeAudit'); if(!box)return;
 const p=activeKnowledge?.payload;
 if(!p){box.innerHTML='<div class="notice"><b>Base de conocimiento no disponible.</b><br><span class="small">No se emitirán conclusiones basadas en datos que no se hayan podido cargar.</span></div>';return}
 const ingredients=Object.keys(activeKnowledge.ingredients||{}).length;
 const rules=Object.keys(activeKnowledge.regulatoryRules||{}).length;
 const sources=(p.sources||[]).length;
 const published=p.publishedAt?String(p.publishedAt).slice(0,10):'No indicada';
 const sourceLabel=knowledgeActivationSource==='verified-server'?'actualización verificada desde backend':'base incluida en la aplicación';
 const monitoring=p.scientificMonitoring?.records||[];
 const monitoringSummary=monitoring.length?`<br><b>Seguimiento SCCS:</b> ${monitoring.filter(x=>x.status==='opinion-final').length} finales · ${monitoring.filter(x=>x.status==='opinion-being-finalised').length} en finalización · ${monitoring.filter(x=>x.status==='mandate').length} mandatos`:'<br><b>Seguimiento SCCS:</b> no disponible';
 const sm=$('scientificMonitoringSummary'); if(sm){sm.innerHTML=monitoring.length?'<div class="mini"><strong>'+monitoring.filter(x=>x.status==='opinion-final').length+'</strong>opiniones finales</div><div class="mini"><strong>'+monitoring.filter(x=>x.status==='opinion-being-finalised').length+'</strong>en finalización</div><div class="mini"><strong>'+monitoring.filter(x=>x.status==='mandate').length+'</strong>mandatos en seguimiento</div><div class="mini"><strong>'+escapeHtml(String(p.scientificMonitoring?.checkedAt||'—'))+'</strong>verificado</div>':'<div class="mini"><strong>—</strong>Sin datos</div>'; }
 box.innerHTML='<div class="two-col"><div class="mini"><strong>DATOS</strong>'+escapeHtml(p.knowledgeVersion)+'</div><div class="mini"><strong>ESQUEMA</strong>v'+escapeHtml(p.schemaVersion)+'</div></div><div class="two-col"><div class="mini"><strong>INGREDIENTES</strong>'+ingredients+'</div><div class="mini"><strong>REGLAS</strong>'+rules+'</div></div><p class="small"><b>Origen de activación:</b> '+escapeHtml(sourceLabel)+'<br><b>Publicado/verificado:</b> '+escapeHtml(published)+'<br><b>Fuentes registradas:</b> '+sources+monitoringSummary+'</p><p class="footer-note">La versión de datos es independiente de la versión de la aplicación. Cambiar estos datos no significa que se haya instalado una nueva función de iOS/Android.</p>'
}
function getCriteria(){try{return JSON.parse(localStorage.getItem('desinzero_criteria')||'["all"]')}catch(e){return ['all']}}
function saveCriteria(){const vals=[...document.querySelectorAll('.criteria button.active')].map(b=>b.dataset.criterion);localStorage.setItem('desinzero_criteria',JSON.stringify(vals.length?vals:['all']))}
function restoreCriteria(){const vals=getCriteria();document.querySelectorAll('.criteria button').forEach(b=>b.classList.toggle('active',vals.includes(b.dataset.criterion)));if(!document.querySelector('.criteria button.active'))document.querySelector('.criteria button[data-criterion="all"]')?.classList.add('active')}
function criterionMatches(info,raw=''){const vals=getCriteria();if(vals.includes('all'))return false;const text=(info?((info.kind||'')+' '+(info.status||'')+' '+(info.note||'')):'')+' '+String(raw||'');return vals.some(v=>v==='perfume'&&/fragancia|perfume/i.test(text))||vals.some(v=>v==='sens'&&/sensibil|fragancia|alérgen/i.test(text))||vals.some(v=>v==='reg'&&/restric|condic|anexo|limit|prohib/i.test(text))||vals.some(v=>v==='evidence'&&info&&info.evidence&&info.evidence!=='strong')||vals.some(v=>v==='nano'&&/\(nano\)|\bnano\b/i.test(text))||vals.some(v=>v==='unknown'&&!info)}
function toggleCriterion(btn){if(btn.dataset.criterion==='all'){document.querySelectorAll('.criteria button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');saveCriteria();return}document.querySelector('.criteria button[data-criterion="all"]')?.classList.remove('active');btn.classList.toggle('active');if(!document.querySelector('.criteria button.active'))document.querySelector('.criteria button[data-criterion="all"]')?.classList.add('active');saveCriteria();if(currentProduct)renderIngredientList(productINCI(currentProduct))}

async function runAppDiagnostics(){
 const required=['home','analyze','scanner','photo','search','compare','criteria','history','updates','legal','ip','privacy','claims','settings','video','barcodeInput','inciText'];
 const tests=[];
 const add=(name,ok,detail='')=>tests.push({name,ok,detail});
 add('Versión de aplicación',/^\d+\.\d+\.\d+$/.test(APP_VERSION),APP_VERSION);
 add('Base de conocimiento activa',!!activeKnowledge?.payload?.knowledgeVersion,activeKnowledge?.payload?.knowledgeVersion||'No disponible');
 add('Base APP/DATOS coherente',activeKnowledge?.payload?.schemaVersion===KNOWLEDGE_SCHEMA,activeKnowledge?.payload?.schemaVersion===KNOWLEDGE_SCHEMA?'Esquema validado':'Esquema no validado');
 required.forEach(id=>add('Elemento '+id,!!document.getElementById(id),!!document.getElementById(id)?'OK':'Falta en la interfaz'));
 try{const k='__dz_qa__';localStorage.setItem(k,'1');const ok=localStorage.getItem(k)==='1';localStorage.removeItem(k);add('Almacenamiento local',ok,ok?'Disponible':'No disponible')}catch(e){add('Almacenamiento local',false,'El navegador ha bloqueado localStorage')}
 add('Secure Context',window.isSecureContext===true,window.isSecureContext?'Disponible':'La cámara y algunas APIs pueden requerir HTTPS o localhost');
 add('Cámara',!!(navigator.mediaDevices&&navigator.mediaDevices.getUserMedia),'API de cámara '+(navigator.mediaDevices?'disponible':'no disponible'));
 add('Detector de códigos',('BarcodeDetector' in window),'El escaneo automático depende de BarcodeDetector; siempre existe la entrada manual');
 add('Web Crypto',!!(window.crypto&&window.crypto.subtle),'SHA-256/operaciones criptográficas del navegador');
 try{const parts=splitINCI('Aqua, Glycerin (and) Citric Acid, Parfum');add('Separación INCI',parts.length===3,parts.length+' elementos detectados')}catch(e){add('Separación INCI',false,e.message)}
 try{const x=escapeHtml('<script>alert(1)<\/script>');add('Sanitización HTML',!x.includes('<script>')&&!x.includes('<\/script>'),'El texto se escapa antes de insertarse en HTML')}catch(e){add('Sanitización HTML',false,e.message)}
 add('Tesseract.js',!!window.Tesseract,'Se carga cuando se inicia OCR; puede requerir conexión en el primer uso');
 add('Versión de conocimiento esperada',activeKnowledge?.payload?.knowledgeVersion==='2026.10.04-016',activeKnowledge?.payload?.knowledgeVersion||'No disponible');
 try{const m=getKnowledge('Limonene');add('Coincidencia exacta INCI',m?.match==='exact'&&m?.id==='limonene','No se fuerza una coincidencia aproximada cuando existe coincidencia exacta')}catch(e){add('Coincidencia exacta INCI',false,e.message)}
 try{const m=getKnowledge('Limonene (nano)');add('Marcado nano conservador',m?.nano===true&&!m?.regulatoryRule,'La forma nano no hereda automáticamente una regla de la forma convencional')}catch(e){add('Marcado nano conservador',false,e.message)}
 try{const m=getKnowledge('Limonene');const x=getKnowledge('Limonnee');add('Detección de posible error OCR',m?.match==='exact'&&x?.match==='possible','Una errata cercana se marca para revisión y no se acepta como exacta')}catch(e){add('Detección de posible error OCR',false,e.message)}
 try{const c=verifiedAutoCorrection('Tocopheryl Acetatf');add('Autocorrección verificada',c?.status==='auto'&&c.corrected==='tocopheryl acetate'&&c.score>=0.87,'Solo se corrigen coincidencias únicas que superan el umbral verificado')}catch(e){add('Autocorrección verificada',false,e.message)}
 try{const a=autoCorrectINCI('Aqua, Tocopheryl Acetatf, IngredienteInventado');add('Autocorrección conservadora',a.corrections.length===1&&a.corrections[0].corrected==='tocopheryl acetate'&&a.review.length===0&&a.text.includes('IngredienteInventado'),'Los términos no verificables permanecen intactos')}catch(e){add('Autocorrección conservadora',false,e.message)}
 const passed=tests.filter(x=>x.ok).length, total=tests.length;
 $('qaSummary').innerHTML='<b>'+passed+'/'+total+' comprobaciones superadas.</b><br><span class="small">Una prueba no disponible no significa que la app sea insegura: puede depender del navegador, permisos o del dispositivo.</span>';
 $('qaResults').innerHTML=tests.map(t=>'<div class="row"><span class="dot '+(t.ok?'green':'amber')+'">'+(t.ok?'✓':'!')+'</span><span><b>'+escapeHtml(t.name)+'</b><br><span class="small">'+escapeHtml(t.detail)+'</span></span></div>').join('');
}

