// V55: release candidate técnico; la PWA conserva actualización verificable. El service worker solo gestiona los recursos de la aplicación;
// las actualizaciones de conocimiento siguen pasando por el manifiesto, SHA-256 y validación de esquema.
if('serviceWorker' in navigator){
  navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!window.__dzReloadedAfterSW){window.__dzReloadedAfterSW=true;window.location.reload();}});
  window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'})
    .then(reg=>{reg.update().catch(()=>{});})
    .catch(()=>{}));
}



// V26 accessibility: modal focus management + Escape + focus trap.
(function initModalAccessibility(){
  const modal=document.getElementById('ingredientModal');
  if(!modal)return;
  const getFocusable=()=>[...modal.querySelectorAll('button,a[href],input,textarea,select,[tabindex]:not([tabindex=\"-1\"])')].filter(x=>!x.disabled&&x.offsetParent!==null);
  const observer=new MutationObserver(()=>{if(modal.classList.contains('open')){const f=getFocusable();if(f.length)f[0].focus()}});
  observer.observe(modal,{attributes:true,attributeFilter:['class']});
  document.addEventListener('keydown',e=>{
    if(!modal.classList.contains('open'))return;
    if(e.key==='Escape'){e.preventDefault();closeIngredient();return}
    if(e.key!=='Tab')return;
    const f=getFocusable();if(!f.length)return;
    const first=f[0],last=f[f.length-1];
    if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
    else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
  });
})();

// DESINZI event delegation: no inline event handlers.
(function initEventDelegation(){
  const actionMap={
    'show-settings':()=>show('settings'),'show-analyze':()=>show('analyze'),'show-home':()=>show('home'),'show-scanner':()=>show('scanner'),'show-photo':()=>show('photo'),'show-search':()=>show('search'),'show-result':()=>show('result'),'show-compare':()=>show('compare'),'show-ingredients':()=>show('ingredients'),'show-claims':()=>show('claims'),'show-history':()=>show('history'),'show-learn':()=>show('learn'),'show-updates':()=>show('updates'),'show-legal':()=>show('legal'),'show-privacy':()=>show('privacy'),'show-ip':()=>show('ip'),'show-criteria':()=>show('criteria'),'show-qa':()=>show('qa'),
    'start-scanner':()=>startScanner(),'stop-scanner':()=>{stopScanner();toast('Cámara detenida')},'analyze-code':()=>analyzeCode(),'run-label-crosscheck':()=>runLabelCrosscheck(),'save-product-context':()=>saveProductContext(),'run-ocr':()=>runOCR(),'clear-ocr':()=>clearOCR(),'revert-ocr-corrections':()=>revertOCRCorrections(),'analyze-inci':()=>analyzeINCI(),'search-product':()=>searchProduct(),'search-compare-product':()=>searchCompareProduct(),'toggle-favorite':()=>toggleFavoriteCurrent(),'start-compare-search':()=>startCompareSearch(),'clear-history':()=>clearHistory(),'export-local-data':()=>exportLocalData(),'clear-local-data':()=>clearLocalData(),'analyze-claim':()=>analyzeClaim(),'export-report':()=>exportAnalysisReport(),'run-diagnostics':()=>runAppDiagnostics(),'check-updates':()=>checkKnowledgeUpdate(),'close-ingredient':()=>closeIngredient(),
    'history-recent':e=>historyTab('recent',e.currentTarget),'history-favorites':e=>historyTab('favorites',e.currentTarget),'history-changes':e=>historyTab('changes',e.currentTarget),
    'toggle-criterion':e=>toggleCriterion(e.currentTarget),
    'open-ingredient':e=>openIngredient(decodeURIComponent(e.currentTarget.dataset.value||'')),
    'select-compare-product':e=>selectCompareProduct(Number(e.currentTarget.dataset.index)),'select-search':e=>selectSearch(Number(e.currentTarget.dataset.index)),
    'open-history':e=>openHistoryItem(e.currentTarget.dataset.id||''),
    'modal-backdrop-close':e=>{if(e.target===e.currentTarget)closeIngredient()}
  };
  document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const fn=actionMap[el.dataset.action];if(fn){e.preventDefault();fn(e);}});
  const photo=document.getElementById('photoInput'); if(photo) photo.addEventListener('change',previewPhoto);
  const barcode=document.getElementById('barcodeInput'); if(barcode) barcode.addEventListener('keydown',e=>{if(e.key==='Enter')analyzeCode();});
  const search=document.getElementById('searchInput'); if(search) search.addEventListener('keydown',e=>{if(e.key==='Enter')searchProduct();});
  const csearch=document.getElementById('compareSearchInput'); if(csearch) csearch.addEventListener('keydown',e=>{if(e.key==='Enter')searchCompareProduct();});
  restoreCriteria();
})();
